async () => {
    const expectedAccountId = "f646b35b9c52945d4a7e6d19909981d8";
    const expectedProjectId = "f987c34e-eb3b-4699-b8fd-e5a3fa22237c";
    const expectedDeploymentId = "4f49f5dc-b6d4-487f-af2b-3d69522183b2";
    const expectedDatabaseId = "c9e9f157-2432-4b55-9a3e-058bf42eb356";
    const output = { before: null, PATCH: null, after: null, error_codes: [] };
    if (accountId !== expectedAccountId) {
      output.error_codes.push("ACCOUNT_ID_PRECONDITION_FAILED");
      return output;
    }
    const path = "/accounts/" + accountId + "/pages/projects/falconos";
    const isRecord = value => value !== null && typeof value === "object" && !Array.isArray(value);
    const has = (object, key) => Object.prototype.hasOwnProperty.call(object, key);
    const canonicalize = value => {
      if (Array.isArray(value)) return value.map(canonicalize);
      if (isRecord(value)) {
        return Object.fromEntries(Object.keys(value).sort().map(key => [key, canonicalize(value[key])]));
      }
      return value;
    };
    const equal = (left, right) => JSON.stringify(canonicalize(left)) === JSON.stringify(canonicalize(right));
    const safeCodes = response => Array.isArray(response.errors)
      ? response.errors.flatMap(error => Number.isInteger(error?.code) ? [error.code] : [])
      : [];
    const request = async (method, body) => {
      try {
        return await cloudflare.request(body === undefined ? { method, path } : { method, path, body });
      } catch (_) {
        return { status: null, success: false, result: null, errors: [], transportFailure: true };
      }
    };
    const httpSummary = (method, response) => ({
      method,
      path,
      status: Number.isInteger(response.status) ? response.status : null,
      success: response.success === true,
      error_codes: response.transportFailure
        ? [method === "PATCH" ? "PATCH_RESULT_UNKNOWN" : "GET_TRANSPORT_ERROR"]
        : safeCodes(response)
    });
    const environmentSummary = config => ({
      d1_binding_id: typeof config?.d1_databases?.WAITLIST_DB?.id === "string"
        ? config.d1_databases.WAITLIST_DB.id
        : null,
      environment_variable_names: isRecord(config?.env_vars) ? Object.keys(config.env_vars).sort() : null
    });
    const projectSummary = project => ({
      id: typeof project?.id === "string" ? project.id : null,
      name: typeof project?.name === "string" ? project.name : null,
      branch: typeof project?.production_branch === "string" ? project.production_branch : null,
      deployment: {
        id: typeof project?.canonical_deployment?.id === "string" ? project.canonical_deployment.id : null,
        branch: typeof project?.canonical_deployment?.deployment_trigger?.metadata?.branch === "string"
          ? project.canonical_deployment.deployment_trigger.metadata.branch
          : null
      },
      production: environmentSummary(project?.deployment_configs?.production),
      preview: environmentSummary(project?.deployment_configs?.preview)
    });
    const httpOkay = response => response.success === true && Number.isInteger(response.status)
      && response.status >= 200 && response.status < 300
      && Array.isArray(response.errors) && response.errors.length === 0;
    const identityErrors = project => {
      const errors = [];
      if (project?.id !== expectedProjectId) errors.push("PROJECT_ID_MISMATCH");
      if (project?.name !== "falconos") errors.push("PROJECT_NAME_MISMATCH");
      if (project?.production_branch !== "main") errors.push("PRODUCTION_BRANCH_MISMATCH");
      if (project?.canonical_deployment?.id !== expectedDeploymentId) errors.push("CANONICAL_DEPLOYMENT_MISMATCH");
      if (project?.canonical_deployment?.environment !== "production") errors.push("CANONICAL_ENVIRONMENT_MISMATCH");
      if (project?.canonical_deployment?.deployment_trigger?.metadata?.branch !== "main") errors.push("CANONICAL_BRANCH_MISMATCH");
      return errors;
    };
    const bindingKeys = new Set([
      "d1_databases", "durable_object_namespaces", "kv_namespaces", "r2_buckets",
      "services", "queue_producers", "analytics_engine_datasets", "vectorize_bindings",
      "ai_bindings", "browsers", "hyperdrive_bindings", "mtls_certificates"
    ]);
    const beforeResponse = await request("GET");
    output.before = { ...httpSummary("GET", beforeResponse), ...projectSummary(beforeResponse.result) };
    if (!httpOkay(beforeResponse)) {
      output.error_codes.push("BEFORE_GET_FAILED");
      return output;
    }
    const before = beforeResponse.result;
    output.error_codes.push(...identityErrors(before));
    if (!isRecord(before?.deployment_configs)) {
      output.error_codes.push("DEPLOYMENT_CONFIGS_PRECONDITION_FAILED");
    }
    for (const environment of ["production", "preview"]) {
      const config = before?.deployment_configs?.[environment];
      const prefix = environment.toUpperCase();
      if (!isRecord(config)) {
        output.error_codes.push(prefix + "_CONFIG_PRECONDITION_FAILED");
        continue;
      }
      if (!isRecord(config.d1_databases) || Object.keys(config.d1_databases).length !== 0) {
        output.error_codes.push(prefix + "_D1_EMPTY_PRECONDITION_FAILED");
      }
      if (!isRecord(config.env_vars) || Object.keys(config.env_vars).length !== 0) {
        output.error_codes.push(prefix + "_ENV_NAMES_EMPTY_PRECONDITION_FAILED");
      }
      for (const key of Object.keys(config)) {
        if (key === "d1_databases") continue;
        if (bindingKeys.has(key) || key === "bindings" || key.endsWith("_bindings")) {
          const value = config[key];
          if (value !== null && (!isRecord(value) || Object.keys(value).length !== 0)) {
            output.error_codes.push(prefix + "_BINDINGS_EMPTY_PRECONDITION_FAILED");
            break;
          }
        }
      }
    }
    if (output.error_codes.length !== 0) return output;

    const beforeConfigs = JSON.parse(JSON.stringify(before.deployment_configs));
    const expectedBinding = { WAITLIST_DB: { id: expectedDatabaseId } };
    const expectedConfigs = JSON.parse(JSON.stringify(beforeConfigs));
    expectedConfigs.production.d1_databases = expectedBinding;
    const body = {
      deployment_configs: {
        production: {
          d1_databases: {
            WAITLIST_DB: { id: expectedDatabaseId }
          }
        }
      }
    };
    const patchResponse = await request("PATCH", body);
    output.PATCH = httpSummary("PATCH", patchResponse);
    if (!httpOkay(patchResponse)) output.error_codes.push("PATCH_NOT_CONFIRMED_SUCCESSFUL");

    const afterResponse = await request("GET");
    output.after = { ...httpSummary("GET", afterResponse), ...projectSummary(afterResponse.result) };
    if (!httpOkay(afterResponse)) {
      output.after.preview_equal = null;
      output.after.unrelated_production_equal = null;
      output.error_codes.push("AFTER_GET_FAILED");
      return output;
    }
    const after = afterResponse.result;
    output.error_codes.push(...identityErrors(after));
    const afterConfigs = after?.deployment_configs;
    const productionWithoutD1 = config => isRecord(config)
      ? Object.fromEntries(Object.entries(config).filter(([key]) => key !== "d1_databases"))
      : null;
    output.after.preview_equal = isRecord(afterConfigs?.preview)
      && equal(beforeConfigs.preview, afterConfigs.preview);
    output.after.unrelated_production_equal = isRecord(afterConfigs?.production)
      && equal(productionWithoutD1(beforeConfigs.production), productionWithoutD1(afterConfigs.production));
    if (!equal(afterConfigs?.production?.d1_databases, expectedBinding)) {
      output.error_codes.push("EXACT_D1_BINDING_VERIFICATION_FAILED");
    }
    if (!output.after.preview_equal) output.error_codes.push("PREVIEW_CONFIG_CHANGED");
    if (!output.after.unrelated_production_equal) output.error_codes.push("UNRELATED_PRODUCTION_CONFIG_CHANGED");
    if (!equal(afterConfigs, expectedConfigs)) output.error_codes.push("FULL_CONFIG_VERIFICATION_FAILED");
    if (!has(afterConfigs?.production || {}, "d1_databases")) output.error_codes.push("D1_BINDING_MISSING");
    return output;
  }

